import { Component, Input, Output, EventEmitter } from '@angular/core';

export interface DropdownItem {
  label: string;
  icon?: string; // name in app-icon
  iconClass?: string;
  action: () => void;
  style?: any;
}

@Component({
  selector: 'app-dropdown-menu',
  template: `
    <div class="relative inline-block text-left" (clickOutside)="isOpen = false">
      <div (click)="toggle($event)">
        <ng-content select="[trigger]"></ng-content>
      </div>

      <div *ngIf="isOpen" 
           class="absolute right-0 mt-2 w-56 origin-top-right bg-white border border-[#262626] rounded-[4px] shadow-lg z-50 ring-1 ring-black ring-opacity-5 focus:outline-none"
           [style.min-width.px]="minWidth">
        <div role="menu" aria-orientation="vertical">
          <ng-content select="[items]"></ng-content>
        </div>
      </div>
    </div>
  `,
  styles: []
})
export class DropdownMenuComponent {
  @Input() minWidth: number = 150;
  isOpen = false;

  toggle(event: Event) {
    event.stopPropagation();
    this.isOpen = !this.isOpen;
  }
}
